 page.goto('http://127.0.0.1:8774/workspace/countries');page.locator('#country-label').fill('India');page.get_by_role('button',name='Load country',exact=True).click();page.get_by_text('This country is not watched. No update comparison.',exact=True).wait_for();page.get_by_role('button',name='Add to watchlist').click();page.get_by_role('button',name='Load country',exact=True).click();page.wait_for_function("() => document.getElementById('watch-update-status').textContent.startsWith('First supplied-view baseline set.')")
