 page.reload();page.get_by_role('button',name='India',exact=True).click();page.wait_for_function("() => document.getElementById('watch-update-status').textContent.startsWith('0 newly seen')");assert page.locator('#watch-update-items p').count()==0
 page.locator('#country-project').select_option('geo');page.get_by_role('button',name='Load country',exact=True).click();page.wait_for_function("() => document.getElementById('watch-update-status').textContent.startsWith('First supplied-view baseline set.')")
